          ? const Value.absent()
          : Value(deletedAt),
      title: Value(title),
      lifeAreaId: lifeAreaId == null && nullToAbsent
          ? const Value.absent()
          : Value(lifeAreaId),
      targetDate: targetDate == null && nullToAbsent
          ? const Value.absent()
          : Value(targetDate),
      doneWhen: doneWhen == null && nullToAbsent
          ? const Value.absent()
          : Value(doneWhen),
      progress: Value(progress),
